Fix errors in this Unity test code.

Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_insert_empty_list(void) {
    node *root = NULL;
    int id = 1;
    int at = 0;
    int bt = 5;
    int prior = 1;

    insert(&root, id, at, bt, prior);

    TEST_ASSERT_NOT_NULL(root);
    TEST_ASSERT_EQUAL_INT(1, root->ID);
    TEST_ASSERT_EQUAL_INT(0, root->AT);
    TEST_ASSERT_EQUAL_INT(5, root->BT);
    TEST_ASSERT_EQUAL_INT(1, root->priority);
    TEST_ASSERT_EQUAL_INT(0, root->CT);
    TEST_ASSERT_EQUAL_INT(0, root->WT);
    TEST_ASSERT_EQUAL_INT(0, root->TAT);
    TEST_ASSERT_NULL(root->next);

    free(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_insert_empty_list);
    return UNITY_END();
}

